import { Fragment, useEffect, useRef, useState, type CSSProperties, type FormEvent, type PointerEvent as ReactPointerEvent } from "react"

// #region story
// Pure: timings and scroll → state. No React, no DOM — the test lifts this region and runs it.
// The motion values are measured from the reference's live preview (see README → Motion).

export const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x)
/** Frame-rate independent approach toward a target (tau in ms). */
export const approach = (cur: number, target: number, dt: number, tau: number) => target + (cur - target) * Math.exp(-Math.max(0, dt) / tau)

/** 0 while an element's top (y, in viewport px) is below a·H, 1 once it has risen to b·H. */
export const windowed = (y: number, H: number, a: number, b: number) => {
  const span = (a - b) * H
  if (!(span > 0)) return y <= b * H ? 1 : 0
  return clamp01((a * H - y) / span)
}

/** Page-load intro: each headline line rises this far, this long, the second line this much later. */
export const INTRO = { rise: 160, ms: 1200, delay: 100, lag: 200 } as const
/** Headings rise in (no fade) when they enter; the line under them follows a beat later. */
export const RISE = { y: 100, ms: 1200, stagger: 150 } as const
/** Team cards fade in when they enter. */
export const FADE = { ms: 500 } as const
/** Capability rows: unlit opacity, and how fast a row lights. */
export const ROW = { dim: 0.4, ms: 500 } as const
/** Big paragraphs: letters go from 40% to full white as the paragraph's top climbs from READ.a·H to READ.b·H. */
export const READ = { dim: 0.4, a: 0.64, b: 0.13 } as const
/** One letter's opacity at reveal progress q (mirrors the CSS clamp(), so the test can check it). */
export const letterAlpha = (q: number, n: number, i: number) => Math.min(1, Math.max(READ.dim, READ.dim + (1 - READ.dim) * (q * (n + 2) - i - 1)))

/** Stacked work cards: each sticks this far from the top, the next arrives after this gap. */
export const STACK = { stick: 8, gap: 60 } as const
/** Reviews drift rightward at this speed (px/s). */
export const MARQUEE_PX_S = 80
export const marqueeSeconds = (halfWidth: number) => Math.max(8, Math.round(halfWidth / MARQUEE_PX_S))

/** The capability row whose centre is nearest the middle line (touch screens follow scroll). */
export const nearestRow = (centers: readonly number[], mid: number) => {
  let best = 0
  let d = Infinity
  centers.forEach((c, i) => {
    const k = Math.abs(c - mid)
    if (k < d) {
      d = k
      best = i
    }
  })
  return best
}

/** Quarterly commitment: 15% off, rounded to the nearest 50. */
export const priceFor = (base: number, quarterly: boolean) => (quarterly ? Math.round((base * 0.85) / 50) * 50 : base)
export const groupDigits = (n: number) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ",")

/** Easter egg: every third tap on the ® turns the silver (argent) to gold (or), and back. */
export const OR_TAPS = 3
export const isOr = (taps: number) => Math.floor(taps / OR_TAPS) % 2 === 1

export const splitWords = (t: string) => t.split(/\s+/).filter(Boolean)
// #endregion

