  ".ag-root[data-or] .ag-hero-glow{background:radial-gradient(closest-side,rgba(255,210,122,.16),rgba(255,210,122,.05) 55%,rgba(255,210,122,0))}",
  ".ag-sculpt{position:absolute;right:clamp(-60px,2vw,40px);top:50%;width:min(70vmin,760px);height:min(70vmin,760px);margin-top:calc(min(70vmin,760px) / -2 - 20px);pointer-events:none;animation:ag-show 1.4s ease-out both}",
  ".ag-turn{width:100%;height:100%;animation:ag-spin 48s linear infinite}",
