  ".ag-hero-quote em{font-size:15px;color:var(--ag-fg)}",
  ".ag-hero-txt{position:absolute;left:0;right:0;bottom:clamp(28px,7vh,72px)}",
  ".ag-h1{font-size:clamp(50px,9vw,140px);line-height:.96;letter-spacing:-.045em;font-weight:300}",
  ".ag-ln{display:block;overflow:hidden;padding-bottom:.07em;margin-bottom:-.07em}",
