  ".ag-ln+.ag-ln>span{animation-delay:.3s}",
  ".ag-h1 .ag-serif{font-size:1.07em;letter-spacing:-.02em}",
  ".ag-hero-row{display:flex;align-items:center;gap:26px;margin-top:34px;flex-wrap:wrap}",
  ".ag-link{font-size:15px;color:var(--ag-mut);transition:color .3s}",
