  ".ag-cue{display:block;width:1px;height:60px;background:linear-gradient(var(--ag-fg),rgba(243,242,239,0));animation:ag-cue 2.4s cubic-bezier(.6,0,.3,1) infinite}",
  /* pill: colours swap in .3s */
