  ".ag-pill::before{content:\"\";position:absolute;inset:0;z-index:-1;border-radius:inherit;background:var(--ag-fg);opacity:0;transition:opacity .3s cubic-bezier(.32,0,.67,0)}",
  ".ag-pill>span{display:inline-flex;align-items:center;gap:10px}",
  ".ag-pill svg{width:14px;height:14px;transition:transform .45s var(--ag-out)}",
  ".ag-pill[data-solid]{color:var(--ag-bg);border-color:var(--ag-fg)}",
  ".ag-pill[data-solid]::before{opacity:1}",
  /* studio + capabilities: letters light from 40% as the paragraph climbs */
  ".ag-big{margin-top:30px;font-size:clamp(28px,4.3vw,62px);line-height:1.12;letter-spacing:-.03em;font-weight:300;max-width:1220px}",
  ".ag-wd{display:inline-block;white-space:nowrap}",
  ".ag-ch{opacity:clamp(.4,calc(.4 + .6 * (var(--q,1) * (var(--n,1) + 2) - var(--i,0) - 1)),1)}",
  ".ag-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:clamp(72px,11vh,130px);align-items:start}",
  ".ag-stat:nth-child(even){margin-top:96px}",
  ".ag-stat{position:relative;aspect-ratio:1/1.1;border:1px solid var(--ag-line);border-radius:24px;padding:22px 24px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;background:linear-gradient(160deg,rgba(255,255,255,.05),rgba(255,255,255,0) 62%)}",
  ".ag-stat-top{position:relative;display:flex;justify-content:space-between;gap:12px;font-size:14px;color:var(--ag-mut)}",
  ".ag-stat-top span+span{color:var(--ag-fg);text-align:right}",
  ".ag-stat-bot{position:relative;display:flex;align-items:flex-end;justify-content:space-between}",
  ".ag-stat-bot svg{width:24px;height:24px;margin-bottom:10px;transition:transform .5s var(--ag-out)}",
  ".ag-stat-n{display:inline-flex;align-items:flex-start;font-size:clamp(46px,5.6vw,88px);line-height:1;letter-spacing:-.05em;font-variant-numeric:tabular-nums}",
  ".ag-stat-n sup{font-size:.5em;line-height:1;margin:.08em 0 0 .04em}",
  ".ag-stat-img{position:absolute;right:-14%;top:20%;width:66%;aspect-ratio:1;opacity:.75;pointer-events:none}",
  ".ag-stat-img img{width:100%;height:100%;object-fit:contain;animation:ag-spin 60s linear infinite}",
  ".ag-th,.ag-row{display:grid;grid-template-columns:1.3fr 1fr .62fr;gap:24px}",
  ".ag-th{margin-top:72px;padding:16px 0;border-top:1px solid var(--ag-line);border-bottom:1px solid var(--ag-line);font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--ag-mut)}",
  ".ag-svc-list{position:relative}",
  ".ag-row{position:relative;padding:clamp(28px,4.6vh,46px) 0;border-bottom:1px solid var(--ag-line)}",
  ".ag-row::before{content:\"\";position:absolute;top:0;bottom:0;left:calc(50% - 50vw);right:calc(50% - 50vw);background:var(--ag-row);opacity:0;transition:opacity .5s cubic-bezier(.65,0,.35,1)}",
  ".ag-row>*{position:relative;opacity:.4;transition:opacity .5s cubic-bezier(.65,0,.35,1)}",
  ".ag-row[data-active]::before,.ag-row[data-active]>*{opacity:1}",
  ".ag-row-t{display:flex;align-items:flex-start;gap:18px;font-size:clamp(30px,3.9vw,58px);line-height:1;letter-spacing:-.035em}",
