  ".ag-row li span{display:inline-block;min-width:34px;color:var(--ag-mut)}",
  ".ag-obj{position:absolute;right:0;top:0;width:clamp(150px,15vw,220px);aspect-ratio:1;transform:translate3d(0,calc(var(--oy,120px) - 50%),0);transition:transform .5s cubic-bezier(.65,0,.35,1);pointer-events:none}",
  ".ag-obj-in{position:relative;width:100%;height:100%}",
  ".ag-obj img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;opacity:0;transform:scale(.85);transition:opacity .5s cubic-bezier(.65,0,.35,1),transform .5s cubic-bezier(.65,0,.35,1)}",
  ".ag-obj img[data-active]{opacity:1;transform:scale(1)}",
  /* work: a plain sticky stack, full height, no shrinking */
  ".ag-stack{position:relative;margin-top:72px}",
  ".ag-card{position:sticky;display:block;height:calc(var(--ag-h) - 18px);min-height:460px;max-height:900px;border-radius:28px;overflow:hidden;background:var(--ag-panel);border:1px solid var(--ag-line)}",
  ".ag-card-media{position:absolute;inset:0}",
  ".ag-card-media img{width:100%;height:100%;object-fit:cover;transition:transform 1.2s var(--ag-out)}",
  ".ag-card-shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.25) 0%,rgba(0,0,0,0) 26%,rgba(0,0,0,0) 50%,rgba(0,0,0,.86) 100%)}",
  ".ag-card-tag{position:absolute;top:22px;left:22px;height:34px;padding:0 14px;display:inline-flex;align-items:center;border-radius:999px;font-size:12px;letter-spacing:.1em;text-transform:uppercase;background:rgba(6,6,7,.42);border:1px solid rgba(243,242,239,.18);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}",
  ".ag-card-meta{position:absolute;left:0;right:0;bottom:0;padding:clamp(20px,2.8vw,36px);display:grid;grid-template-columns:1fr 1.7fr .9fr .5fr;gap:24px;font-size:15px;line-height:1.5}",
  ".ag-card-meta small{display:block;margin-bottom:8px;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--ag-mut)}",
  ".ag-card-meta b{display:block;font-size:clamp(28px,3vw,44px);line-height:1}",
  /* honours */
