  ".ag-hon-band{position:absolute;inset:0;clip-path:inset(0 100% 0 0);transition:clip-path .75s cubic-bezier(.7,0,.2,1)}",
  ".ag-hon-band img{width:100%;height:100%;object-fit:cover;filter:brightness(.72)}",
  ".ag-hon-row:focus-visible .ag-hon-band{clip-path:inset(0 0 0 0)}",
