  ".ag-hon-t{font-size:clamp(26px,3.6vw,54px);line-height:1.04;letter-spacing:-.035em;transition:transform .7s var(--ag-out)}",
  ".ag-hon-t small{display:block;margin-top:8px;font-size:14px;letter-spacing:0;color:var(--ag-mut);transition:color .5s}",
  ".ag-hon-y{font-size:14px;color:var(--ag-mut);font-variant-numeric:tabular-nums;transition:color .5s}",
  /* people */
  ".ag-team{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:60px}",
