  ".ag-mem-ph img{width:100%;height:100%;object-fit:cover;filter:grayscale(1) contrast(1.06);transition:transform 1.1s var(--ag-out),filter .7s ease}",
  ".ag-mem-tx{padding:20px 20px 24px;text-align:center}",
