  ".ag-mem-tx p{margin-top:16px;font-size:14px;line-height:1.6;color:var(--ag-mut)}",
  ".ag-join{position:relative;margin-top:16px;border-radius:28px;overflow:hidden;border:1px solid var(--ag-line);min-height:clamp(380px,56vh,560px);padding:clamp(24px,4vw,52px);display:flex;flex-direction:column;justify-content:space-between;gap:40px;background:radial-gradient(120% 100% at 90% 0%,#1b1b20,#08080a 62%)}",
  ".ag-arc{position:absolute;display:block;border-radius:50%;border:1.5px solid rgba(255,255,255,.9);box-shadow:0 0 22px rgba(255,255,255,.4),inset 0 0 22px rgba(255,255,255,.22);pointer-events:none;-webkit-mask-image:conic-gradient(from 0deg,transparent 0 12%,#000 34%,#000 52%,transparent 78%);mask-image:conic-gradient(from 0deg,transparent 0 12%,#000 34%,#000 52%,transparent 78%);animation:ag-spin 36s linear infinite}",
  ".ag-arc1{width:1100px;height:1100px;right:-640px;top:-560px}",
  ".ag-arc2{width:860px;height:860px;right:-300px;top:40px;animation-duration:48s;animation-direction:reverse;opacity:.75}",
  ".ag-root[data-or] .ag-arc{border-color:rgba(255,224,160,.95);box-shadow:0 0 22px rgba(255,200,110,.45),inset 0 0 22px rgba(255,200,110,.25)}",
  ".ag-join h3{position:relative;font-size:clamp(40px,6.4vw,96px);line-height:1;letter-spacing:-.04em;font-weight:300}",
