  ".ag-toggle[data-q] .ag-toggle-k{transform:translateX(100%)}",
  ".ag-save{font-size:11px;font-weight:500;padding:3px 8px;border-radius:999px;background:var(--ag-chrome);color:#111}",
  ".ag-plans{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:52px}",
  ".ag-plan{display:flex;flex-direction:column;border-radius:28px;border:1px solid var(--ag-line);padding:clamp(24px,3vw,40px);background:linear-gradient(170deg,rgba(255,255,255,.05),rgba(255,255,255,.01))}",
  ".ag-plan[data-hot]{background:linear-gradient(170deg,#1a1a1f,#0b0b0d 70%);border-color:rgba(243,242,239,.26)}",
