  ".ag-plan .ag-pill{width:100%}",
  /* voices: one row drifting right */
  ".ag-marq{margin-top:52px;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent);mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent)}",
  ".ag-track{display:flex;gap:16px;width:max-content;animation:ag-marq var(--marq,33s) linear infinite}",
  ".ag-marq:hover .ag-track{animation-play-state:paused}",
  ".ag-quote{flex:none;width:clamp(290px,30vw,420px);display:flex;flex-direction:column;justify-content:space-between;gap:30px;padding:26px;border-radius:24px;border:1px solid var(--ag-line);background:linear-gradient(170deg,#18181b,#0d0d0f)}",
